import { RFCNodeAddonProvider } from '../BAPINodeAddonProvider';
import { RFCClientConnectionHandler } from './BAPIClientConnectionHandler';
import { RFCClientAddonConnectionHandler } from './BAPIClientAddonConnectionHandler';
import { RFCConnectionParameters } from './BAPIConnectionParameters';
import { Logger } from './Logger';
/** @internal */
export class InstanceProvider {
  public static get Instance() {
    return new InstanceProvider();
  }
  public async createBapiClientConnectionHandler(
    connectionParam: RFCConnectionParameters,
    logger: Logger,
  ): Promise<RFCClientConnectionHandler> {
    const addonInstance = RFCNodeAddonProvider.createBAPIClientAddon(logger);
    const bapiClientConnectionHandler = new RFCClientAddonConnectionHandler(
      connectionParam,
      addonInstance,
      logger,
    );
    await bapiClientConnectionHandler.open();
    return bapiClientConnectionHandler;
  }
}
