import { BaseError } from './BaseError';

/**
 * @description Represents an error thrown by the utility conversion method.
 */
export class RFCUtilityError extends BaseError {
  /** @internal */
  constructor(message: string) {
    super(message, 'RFCUtilityError');
    this.message = message;
  }
  /**
   * @description Error message.
   */
  message: string;
}
