import { BaseError } from './BaseError';

/**
 * @description RFC Error code.
 */
export enum RFCErrorCode {
  /**
   * @description Error in Network & Communication layer.
   */
  RFC_COMMUNICATION_FAILURE = 1,
  /**
   * @description Unable to logon to SAP system. Invalid password, user locked, etc.
   */
  RFC_LOGON_FAILURE,
  /**
   * @description SAP system runtime error (SYSTEM_FAILURE): Shortdump on the backend side
   */
  RFC_ABAP_RUNTIME_FAILURE,
  /**
   * @description The called function module raised an E-, A- or X-Message
   */
  RFC_ABAP_MESSAGE,
  /**
   * @description The called function module raised an Exception (RAISE or MESSAGE ... RAISING)
   */
  RFC_ABAP_EXCEPTION,
  /**
   * @description Connection closed by the other side
   */
  RFC_CLOSED,
  /**
   * @description No longer used
   */
  RFC_CANCELED,
   /**
   * @description No longer used
   */
  RFC_TIMEOUT,
  /**
   * @description Memory insufficient
   */
  RFC_MEMORY_INSUFFICIENT,
  /**
   * @description Version mismatch
   */
  RFC_VERSION_MISMATCH,
  /**
   * @description The received data has an unsupported format
   */
  RFC_INVALID_PROTOCOL,
  /**
   * @description A problem while serializing or deserializing RFM parameters
   */
  RFC_SERIALIZATION_FAILURE,
  /**
   * @description An invalid handle was passed to an API call
   */
  RFC_INVALID_HANDLE,
  /**
   * @description RfcListenAndDispatch did not receive an RFC request during the timeout period
   */
  RFC_RETRY,
  /**
   * @description Error in external custom code. (E.g. in the function handlers or tRFC handlers.) Results in SYSTEM_FAILURE
   */
  RFC_EXTERNAL_FAILURE,
  /**
   * @description Inbound tRFC Call already executed (needs to be returned from RFC_ON_CHECK_TRANSACTION in case the TID is already known and successfully processed before.)
   */
  RFC_EXECUTED,
  /**
   * @description Function or structure definition not found (Metadata API)
   */
  RFC_NOT_FOUND,
  /**
   * @description The operation is not supported on that handle
   */
  RFC_NOT_SUPPORTED,
  /**
   * @description The operation is not supported on that handle at the current point of time (e.g. trying a callback on a server handle, while not in a call)
   */
  RFC_ILLEGAL_STATE,
  /**
   * @description An invalid parameter was passed to an API call, (e.g. invalid name, type or length)
   */
  RFC_INVALID_PARAMETER,
   /**
   * @description Codepage conversion error
   */
  RFC_CODEPAGE_CONVERSION_FAILURE,
   /**
   * @description Error while converting a parameter to the correct data type
   */
  RFC_CONVERSION_FAILURE,
  /**
   * @description The given buffer was to small to hold the entire parameter. Data has been truncated.
   */
  RFC_BUFFER_TOO_SMALL,
  /**
   * @description Trying to move the current position before the first row of the table
   */
  RFC_TABLE_MOVE_BOF,
  /**
   * @description Trying to move the current position after the last row of the table
   */
  RFC_TABLE_MOVE_EOF,
  /**
   * @description Failed to start and attach SAPGUI to the RFC connection
   */
  RFC_START_SAPGUI_FAILURE,
  /**
   * @description The called function module raised a class based exception
   */
  RFC_ABAP_CLASS_EXCEPTION,
  /**
   * @description "Something" went wrong, but I don't know what...
   */
  RFC_UNKNOWN_ERROR,
   /**
   * @description Authorization check error
   */
  RFC_AUTHORIZATION_FAILURE,
  /**
   * @description The authentication handler (RFC_ON_AUTHENTICATION_CHECK) failed to authenticate the user trying to log on
   */
  RFC_AUTHENTICATION_FAILURE,
  /**
   * @description Error when dealing with functions provided by the cryptolibrary
   */
  RFC_CRYPTOLIB_FAILURE,
  /**
   * @description Error when dealing with io functions, streams etc
   */
  RFC_IO_FAILURE,
  /**
   * @description Requesting or freeing critical sections or mutex failed
   */
  RFC_LOCKING_FAILURE,
  /**
   * @description Don't use
   */
  _RFC_RC_max_value,
}

/**
 * @description Groups several error conditions together, depending on the "layer" to which they belong.
 */
export enum RFCErrorGroup {
  /**
   * @description ABAP Exception raised in ABAP function modules.
   */
  ABAP_APPLICATION_FAILURE = 1,
  /**
   * @description ABAP Message raised in ABAP function modules or in ABAP runtime of the backend (e.g Kernel)
   */
  ABAP_RUNTIME_FAILURE,
  /**
   * @description Error message raised when logon fails
   */
  LOGON_FAILURE,
  /**
   * @description Problems with the network connection (or backend broke down and killed the connection)
   */
  COMMUNICATION_FAILURE,
  /**
   * @description Problems in the RFC runtime of the external program (i.e "this" library)
   */
  EXTERNAL_RUNTIME_FAILURE,
  /**
   * @description Problems in the external program (e.g in the external server implementation)
   */
  EXTERNAL_APPLICATION_FAILURE,
  /**
   * @description Problems raised in the authorization check handler provided by the external server implementation
   */
  EXTERNAL_AUTHORIZATION_FAILURE,
  /**
   * @description Problems raised by the authentication handler (RFC_ON_AUTHENTICATION_CHECK)
   */
  EXTERNAL_AUTHENTICATION_FAILURE,
  /**
   * @description Problems when dealing with functions provided by the cryptolibrary
   */
  CRYPTOLIB_FAILURE,
  /**
   * @description LOCKING_FAILURE
   */
  LOCKING_FAILURE,
}

/**
 * @description Represents an error thrown by the S/4 system or the NWRFCSDK.
 */
export interface RfcErrorInfo {
  /**
   * @description Error code.
   */
  code: RFCErrorCode;
  /**
   * @description Error group.
   */
  group: RFCErrorGroup;
  /**
   * @description Error key.
   */
  key: string;
  /**
   * @description Error message.
   */
  message: string;
}

/**
 * @description Represents an error thrown by the S/4 system or the NWRFCSDK.
 */
export class RFCError extends BaseError implements RfcErrorInfo {
  /** @internal */
  constructor(errorInfo: RfcErrorInfo) {
    super(errorInfo.message, 'RFCError');
    this.code = errorInfo.code;
    this.group = errorInfo.group;
    this.key = errorInfo.key;
    this.message = errorInfo.message;
  }
  /**
   * @description Error code.
   */
  code: RFCErrorCode;
  /**
   * @description Error group.
   */
  group: RFCErrorGroup;
  /**
   * @description Error key.
   */
  key: string;
  /**
   * @description Error message.
   */
  message: string;
}
