import path from 'path';
import os from 'os';
import { RFCClientAddon } from './client/BAPIClientAddon';
import { Logger } from './client/Logger';

/** @internal */
export interface LibraryUtilAddon {
  LoadNWRFCSDK(libPath: string, isWindows: boolean, isLinux: boolean): void;
}

/** @internal */
export interface RFCNodeAddon {
  BAPIClientAddon: RFCClientAddon;
  LibraryUtilAddon: LibraryUtilAddon;
}
/** @internal */
export class RFCNodeAddonProvider {
  private static nodeAddon: RFCNodeAddon;

  static createBAPIClientAddon(logger: Logger): RFCClientAddon {
    RFCNodeAddonProvider.loadAddon();
    return (new (RFCNodeAddonProvider.nodeAddon as any).BAPIClientAddon(logger)) as RFCClientAddon;
  }

  private static loadAddon(): void {
    if (!RFCNodeAddonProvider.nodeAddon) {
    const currentPlatform = os.platform();
    const libPath = path.resolve(
      __dirname,
      `./sapnoderfcaddons/nwrfcsdk/${currentPlatform}/lib/`,
    );

    RFCNodeAddonProvider.nodeAddon = eval('require')(
      this.getPrebuildAddonPath(),
    ) as RFCNodeAddon;

    RFCNodeAddonProvider.nodeAddon.LibraryUtilAddon.LoadNWRFCSDK(
      libPath,
      currentPlatform === 'win32',
      currentPlatform === 'linux',
    );
  }
  }

  private static getPrebuildAddonPath(): string {
    return path.resolve(
      __dirname,
      './sapnoderfcaddons',
      'prebuilds',
      `${os.platform()}-${os.arch()}`,
      '@sap-rfc+node-rfc-library.node',
    );
  }
}
