import { BaseError } from './BaseError';

/**
 * @description Enum representing different errors that can be thrown by the <b>@sap-rfc/node-rfc-library</b>.
 */
export enum NodeRFCLibraryErrorCode {
  /**
   * @description Unknown error.
   */
  UNKNOW_ERROR,
  /**
   * @description Empty connection parameter.
   */
  EMPTY_CONNECTIONPARAM,
  /**
   * @description Invalid connection parameter key.
   */
  INVALID_CONNECTION_PARAM_KEY,
  /**
   * @description Invalid connection parameter value.
   */
  INVALID_CONNECTION_PARAM_VALUE,
   /**
   * @description Connection is already closed.
   */
  CONNECTION_CLOSED,
  /**
   * @description Failed to load dependency.
   */
  FAILED_TO_LOAD_DEPENDENCY,
  /**
   * @description Unsupported data type.
   */
  UNSUPPORTED_FIELD_DATATYPE,
  /**
   * @description Error in excluding parameter.
   */
  FAILED_TO_EXCLUDE_PARAMETER,
  /**
   * @description Invalid Field Value.
   */
  INVALID_FIELD_VALUE,
  /**
   * @description Input Parameters are not valid.
   */
  INPUT_PARAMETER_VALIDATION_FAILED
}

/**
 * @description Represents an error thrown by the <b>@sap-rfc/node-rfc-librayr</b>.
 */
export interface NodeRFCLibraryErrorInfo {
  /**
   * @description Error code.
   */
  code: NodeRFCLibraryErrorCode;
  /**
   * @description Error message.
   */
  message: string;
}

/**
 * @description Represents an error thrown by the <b>@sap-rfc/node-rfc-librayr</b>.
 */
export class NodeRFCLibraryError
  extends BaseError
  implements NodeRFCLibraryErrorInfo {
  /** @internal */
  constructor(errorInfo: NodeRFCLibraryErrorInfo) {
    super(errorInfo.message, 'RFCClientError');
    this.code = errorInfo.code;
    this.message = errorInfo.message;
  }
   /**
   * @description Error code.
   */
  code: NodeRFCLibraryErrorCode;
   /**
   * @description Error code.
   */
  message: string;
  /** @internal */
  static unKnowError(message: string) {
    return new NodeRFCLibraryError({
      code: NodeRFCLibraryErrorCode.UNKNOW_ERROR,
      message,
    });
  }
}
