import { RFCClientConnectionHandler } from './BAPIClientConnectionHandler';
import { RFCConnectionParameters } from './BAPIConnectionParameters';
import { InstanceProvider } from './InstanceProvider';
import { Logger } from './Logger';
import { DefaultLogger } from './DefaultLogger';

/**
 * @description RFC Client. Use an object of this class to open a connection to a S/4 system.
 *
 */
export class RFCClient {
  private readonly logger: Logger;
  private readonly instanceProvider: InstanceProvider;
  /**
   * @description If the user does not pass a logger into the contructor. By default a console logger is used.
   */
  constructor(logger: Logger = new DefaultLogger()) {
    this.logger = logger;
    if (typeof(logger.log) != 'function') {
      this.logger = new DefaultLogger();
    }

    this.instanceProvider = InstanceProvider.Instance;
  }
  /**
   * @description Opens a connection to the S/4 system.
   * @param connectionParam - The connection parameters relevant for opening the connection.
   * @returns A connection object representing a connection to the S/4 system. RFCs can be executed using this connection object.
   * @throws {RFCError} An error from the S/4 system or the underlying NWRFCSDK.
   * @throws {NodeRFCLibraryError} An error thrown by the @sap-rfc/node-rfc-library.
   */
  async open(
    connectionParam: RFCConnectionParameters,
  ): Promise<RFCClientConnectionHandler> {
    this.logger.log('debug', 'Entering BAPIClient::Open');
    return this.instanceProvider.createBapiClientConnectionHandler(
      connectionParam,
      this.logger,
    );
  }
}
