import { RFCClientAddon } from './BAPIClientAddon';
import {
  RFCClientConnectionHandler,
  RFCInputParams,
  RFCObject,
} from './BAPIClientConnectionHandler';
import { Logger } from './Logger';
import { RFCConnectionParameters } from './BAPIConnectionParameters';
import { BAPIExecuteParameters } from '../models/BAPIClientAddon.model';
import { NodeRFCLibraryError, NodeRFCLibraryErrorInfo } from '../error/NodeRFCLibraryError';
import { RFCError, RfcErrorInfo } from '../error/RFCError';
import { RFCMetadata } from '../models/rfcMetadata.model';

/** @internal */
export class RFCClientAddonConnectionHandler
  implements RFCClientConnectionHandler {
  private readonly bapiClientAddon: RFCClientAddon;
  private readonly logger: Logger;
  private readonly connectionParam: RFCConnectionParameters;
  constructor(
    connectionParam: RFCConnectionParameters,
    bapiClientAddon: RFCClientAddon,
    logger: Logger,
  ) {
    this.bapiClientAddon = bapiClientAddon;
    this.logger = logger;
    this.connectionParam = connectionParam;
  }

  private throwException(error: any) {
    if (error.exceptionType === 'RFCException') {
      throw new RFCError(error as RfcErrorInfo);
    } else if (error.exceptionType === 'NodeRFCLibraryException') {
      throw new NodeRFCLibraryError(error as NodeRFCLibraryErrorInfo);
    }
    throw NodeRFCLibraryError.unKnowError(error as string);
  }

  async open(): Promise<void> {
    try {
      this.logger.log(
        'debug',
        'entering BAPIClientAddonConnectionHandler::open',
      );
      await this.bapiClientAddon.openConnection(this.connectionParam);
      this.logger.log(
        'debug',
        'leaving BAPIClientAddonConnectionHandler::open',
      );
    } catch (error: any) {
      this.throwException(error);
    }
  }

  async execute(
    rfcName: string,
    input: RFCInputParams,
    paramsToExcludeFromOutput?: string[],
  ): Promise<RFCObject> {
    try {
      this.logger.log(
        'debug',
        'entering BAPIClientAddonConnectionHandler::execute',
      );
      const executeParameters: BAPIExecuteParameters = {
        bapiName: rfcName,
        inputParameters: {
          ...input?.import,
          ...input?.changing,
          ...input?.table,
        },
        enableValidation: true,
        paramsToExcludeFromOutput: paramsToExcludeFromOutput ?? [],
      };

      this.logger.log(
        'debug',
        'leaving BAPIClientAddonConnectionHandler::execute',
      );
      return await this.bapiClientAddon.executeBAPI(
        executeParameters,
      );
    } catch (error: any) {
      this.throwException(error);
    }
    return {} as RFCObject;
  }

  async commit(): Promise<void> {
    try {
      this.logger.log(
        'debug',
        'entering BAPIClientAddonConnectionHandler::commit',
      );
      await this.bapiClientAddon.commitBAPI();
      this.logger.log(
        'debug',
        'leaving BAPIClientAddonConnectionHandler::commit',
      );
    } catch (error: any) {
      this.throwException(error);
    }
  }

  async close(): Promise<void> {
    try {
      this.logger.log(
        'debug',
        'entering BAPIClientAddonConnectionHandler::close',
      );
      await this.bapiClientAddon.closeConnection();
      this.logger.log(
        'debug',
        'Leaving BAPIClientAddonConnectionHandler::close',
      );
    } catch (error: any) {
      this.throwException(error);
    }
  }

  async getMetadata(rfcName: string): Promise<RFCMetadata> {
      this.logger.log(
        'debug',
        'entering BAPIClientAddonConnectionHandler::getMetadata',
      );
      if (!rfcName) {
        this.logger.log('error', 'rfcName is not passed in.');
        throw NodeRFCLibraryError.unKnowError('rfcName is a mandatory parameter.');
      }
      try {
        return await this.bapiClientAddon.getMetadata(rfcName);
      } catch (error: any) {
        this.throwException(error);
      }
    return {} as RFCMetadata;
  }
}
