import { UtilityErrorMessages } from './constants';
import { RFCUtilityError } from './error/RFCUtilityError';
import {
  AbapDatatype,
  AbapType,
  JsonDataType,
  JavaScriptType,
} from './models/BAPIUtility.model';

  /**
   * @description Utility to convert ABAP types to a javascript types.
   */
const RFCUtility = {
  /**
   * @description Converts an ABAP type to a javascript type.
   * @throws {RFCUtilityError} Thrown when an unknown abap type is passed as input.
   */
  convertAbapTypeToJavaScriptType(abapType: AbapType): JavaScriptType {
    switch (abapType) {
      case AbapDatatype.Int1:
      case AbapDatatype.Int4:
      case AbapDatatype.Int2:
        return JsonDataType.Number;
      case AbapDatatype.Number:
      case AbapDatatype.Char:
      case AbapDatatype.CharVariable:
      case AbapDatatype.BCD:
      case AbapDatatype.Date:
      case AbapDatatype.Time:
      case AbapDatatype.Decf16:
      case AbapDatatype.Decf34:
      case AbapDatatype.Float:
        return JsonDataType.String;
      case AbapDatatype.ByteVariable:
      case AbapDatatype.Byte:
        return JsonDataType.Buffer;
      case AbapDatatype.Int8:
      case AbapDatatype.UtcLong:
        return JsonDataType.BigInt;
      default:
        throw new RFCUtilityError(UtilityErrorMessages.UNSUPPORTED_DATATYPE);
    }
  },
};

export { RFCUtility };
